        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def tdiv(a, b):
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while True:
            tok = peek()
            if tok is not None and tok[0] in ('+', '-'):
                advance()
                rhs = parse_term()
                if tok[0] == '+':
                    val = val + rhs
                else:
                    val = val - rhs
            else:
                break
        return val

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while True:
            tok = peek()
            if tok is not None and tok[0] in ('*', '/'):
                advance()
                rhs = parse_factor()
                if tok[0] == '*':
                    val = val * rhs
                else:
                    val = tdiv(val, rhs)
            else:
                break
        return val

    def parse_factor():
        nonlocal pos
        tok = peek()
        if tok is not None and tok[0] == '-':
            advance()
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'NUM':
            advance()
            return tok[1]
        if tok[0] == '(':
            advance()
            val = parse_expr()
            tok2 = peek()
            if tok2 is None or tok2[0] != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return val
        raise ValueError(f"Unexpected token: {tok}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

